create or replace function sales._settlement_id_for_order(
  p_tenant_id uuid,
  p_sales_order_id uuid
) returns uuid
language plpgsql
security definer
set search_path = sales, iam, public, pg_temp
as $$
declare
  v_id uuid;
begin
  select id into v_id
  from sales.sales_order_settlements
  where tenant_id = p_tenant_id and sales_order_id = p_sales_order_id;
  if v_id is null then
    raise exception using message = jsonb_build_object(
      'code', 'REFERENCE_UNAVAILABLE',
      'message', 'Settlement was not found.'
    )::text;
  end if;
  return v_id;
end;
$$;

create or replace function sales._settlement_mutation_snapshot(
  p_tenant_id uuid,
  p_settlement_id uuid,
  p_transaction_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = sales, iam, public, pg_temp
as $$
declare
  v_s sales.sales_order_settlements%rowtype;
begin
  select * into v_s
  from sales.sales_order_settlements
  where tenant_id = p_tenant_id and id = p_settlement_id;

  return jsonb_build_object(
    'settlementId', v_s.id::text,
    'salesOrderId', v_s.sales_order_id::text,
    'transactionId', p_transaction_id::text,
    'currencyCode', v_s.currency_code,
    'currentPayableMinor', v_s.current_payable_amount_minor,
    'collectedMinor', v_s.collected_amount_minor,
    'refundedMinor', v_s.refunded_amount_minor,
    'netCollectedMinor', v_s.net_collected_amount_minor,
    'outstandingMinor', v_s.outstanding_amount_minor,
    'paymentStatus', v_s.payment_status,
    'version', v_s.version
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- record_sales_payment
-- ---------------------------------------------------------------------------
create or replace function sales.record_sales_payment(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_store_id uuid,
  p_sales_order_id uuid,
  p_amount_minor bigint,
  p_payment_method_code text,
  p_idempotency_key text,
  p_payload_hash text,
  p_source_context text default 'additional_collection',
  p_payment_method_snapshot jsonb default null,
  p_external_reference text default null,
  p_correlation_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = sales, iam, public, pg_temp
as $$
declare
  v_decision jsonb;
  v_settlement_id uuid;
  v_currency text;
  v_outstanding bigint;
  v_order_store uuid;
  v_tx_id uuid := gen_random_uuid();
  v_result jsonb;
  v_correlation uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  perform sales._assert_sales_actor(p_tenant_id, p_actor_id, p_store_id, 'sales.payment.record');

  if coalesce(p_amount_minor, 0) <= 0
     or nullif(trim(coalesce(p_payment_method_code, '')), '') is null
     or nullif(trim(coalesce(p_idempotency_key, '')), '') is null
     or nullif(trim(coalesce(p_payload_hash, '')), '') is null then
    raise exception using message = jsonb_build_object(
      'code', 'CONTEXT_INVALID',
      'message', 'Payment context is invalid.'
    )::text;
  end if;

  select store_id into v_order_store
  from sales.sales_orders
  where tenant_id = p_tenant_id and id = p_sales_order_id;
  if not found or v_order_store is distinct from p_store_id then
    raise exception using message = jsonb_build_object(
      'code', 'REFERENCE_UNAVAILABLE',
      'message', 'Sales order was not found in store scope.'
    )::text;
  end if;

  v_decision := sales._begin_sales_idempotency(
    p_tenant_id,
    'record_sales_payment',
    trim(p_idempotency_key),
    trim(p_payload_hash),
    v_correlation
  );
  if v_decision->>'decision' = 'replay' then
    return v_decision->'result_snapshot';
  end if;
  if v_decision->>'decision' = 'in_progress' then
    raise exception using message = jsonb_build_object(
      'code', 'IDEMPOTENCY_CONFLICT',
      'message', 'Idempotency key is already in progress.'
    )::text;
  end if;

  v_settlement_id := sales._settlement_id_for_order(p_tenant_id, p_sales_order_id);
  select currency_code, outstanding_amount_minor
  into v_currency, v_outstanding
  from sales.sales_order_settlements
  where tenant_id = p_tenant_id and id = v_settlement_id
  for update;

  if p_amount_minor > v_outstanding then
    raise exception using message = jsonb_build_object(
      'code', 'OVERPAYMENT_NOT_ALLOWED',
      'message', 'Payment exceeds outstanding payable.'
    )::text;
  end if;

  insert into sales.sales_payment_transactions(
    id, tenant_id, sales_order_settlement_id, transaction_code, transaction_type, direction,
    amount_minor, currency_code, payment_method_code, payment_method_snapshot, status,
    source_context, source_type, source_id, initiated_by_user_id, confirmed_by_user_id,
    idempotency_key, external_reference, occurred_at, confirmed_at
  ) values (
    v_tx_id, p_tenant_id, v_settlement_id,
    'PMT-' || upper(substr(replace(v_tx_id::text, '-', ''), 1, 16)),
    'collection', 'inflow', p_amount_minor, v_currency, trim(p_payment_method_code),
    p_payment_method_snapshot, 'confirmed',
    coalesce(nullif(trim(p_source_context), ''), 'additional_collection'),
    'sales_order', p_sales_order_id, p_actor_id, p_actor_id,
    trim(p_idempotency_key), nullif(trim(coalesce(p_external_reference, '')), ''),
    now(), now()
  );

  perform sales._recompute_sales_settlement(p_tenant_id, v_settlement_id);
  v_result := sales._settlement_mutation_snapshot(p_tenant_id, v_settlement_id, v_tx_id);

  insert into sales.outbox_messages(id, tenant_id, event_type, payload)
  values (
    gen_random_uuid(), p_tenant_id, 'sales.payment.recorded',
    jsonb_build_object(
      'salesOrderId', p_sales_order_id::text,
      'settlementId', v_settlement_id::text,
      'transactionId', v_tx_id::text,
      'amountMinor', p_amount_minor,
      'correlationId', v_correlation::text
    )
  );

  perform sales._complete_sales_idempotency(
    p_tenant_id,
    'record_sales_payment',
    trim(p_idempotency_key),
    'succeeded',
    'sales_payment_transaction',
    v_tx_id,
    v_result
  );

  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- record_sales_refund
-- ---------------------------------------------------------------------------
create or replace function sales.record_sales_refund(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_store_id uuid,
  p_sales_order_id uuid,
  p_amount_minor bigint,
  p_payment_method_code text,
  p_reason_code text,
  p_idempotency_key text,
  p_payload_hash text,
  p_related_transaction_id uuid default null,
  p_source_context text default 'manual_correction',
  p_reason text default null,
  p_correlation_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = sales, iam, public, pg_temp
as $$
declare
  v_decision jsonb;
  v_settlement_id uuid;
  v_currency text;
  v_net bigint;
  v_order_store uuid;
  v_related sales.sales_payment_transactions%rowtype;
  v_tx_id uuid := gen_random_uuid();
  v_result jsonb;
  v_correlation uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  perform sales._assert_sales_actor(p_tenant_id, p_actor_id, p_store_id, 'sales.payment.refund');

  if coalesce(p_amount_minor, 0) <= 0
     or nullif(trim(coalesce(p_payment_method_code, '')), '') is null
     or nullif(trim(coalesce(p_reason_code, '')), '') is null
     or nullif(trim(coalesce(p_idempotency_key, '')), '') is null
     or nullif(trim(coalesce(p_payload_hash, '')), '') is null then
    raise exception using message = jsonb_build_object(
      'code', 'CONTEXT_INVALID',
      'message', 'Refund context is invalid.'
    )::text;
  end if;

  select store_id into v_order_store
  from sales.sales_orders
  where tenant_id = p_tenant_id and id = p_sales_order_id;
  if not found or v_order_store is distinct from p_store_id then
    raise exception using message = jsonb_build_object(
      'code', 'REFERENCE_UNAVAILABLE',
      'message', 'Sales order was not found in store scope.'
    )::text;
  end if;

  v_decision := sales._begin_sales_idempotency(
    p_tenant_id,
    'record_sales_refund',
    trim(p_idempotency_key),
    trim(p_payload_hash),
    v_correlation
  );
  if v_decision->>'decision' = 'replay' then
    return v_decision->'result_snapshot';
  end if;
  if v_decision->>'decision' = 'in_progress' then
    raise exception using message = jsonb_build_object(
      'code', 'IDEMPOTENCY_CONFLICT',
      'message', 'Idempotency key is already in progress.'
    )::text;
  end if;

  v_settlement_id := sales._settlement_id_for_order(p_tenant_id, p_sales_order_id);
  select currency_code, net_collected_amount_minor
  into v_currency, v_net
  from sales.sales_order_settlements
  where tenant_id = p_tenant_id and id = v_settlement_id
  for update;

  if p_related_transaction_id is not null then
    select * into v_related
    from sales.sales_payment_transactions
    where tenant_id = p_tenant_id
      and id = p_related_transaction_id
      and sales_order_settlement_id = v_settlement_id
    for update;
    if not found then
      raise exception using message = jsonb_build_object(
        'code', 'REFERENCE_UNAVAILABLE',
        'message', 'Related payment transaction was not found on this settlement.'
      )::text;
    end if;
    if v_related.status <> 'confirmed'
       or v_related.direction <> 'inflow'
       or v_related.transaction_type <> 'collection' then
      raise exception using message = jsonb_build_object(
        'code', 'CONTEXT_INVALID',
        'message', 'Related transaction is not a refundable collection.'
      )::text;
    end if;
  end if;

  if p_amount_minor > v_net then
    raise exception using message = jsonb_build_object(
      'code', 'REFUND_EXCEEDS_COLLECTED',
      'message', 'Refund exceeds net collected amount.'
    )::text;
  end if;

  insert into sales.sales_payment_transactions(
    id, tenant_id, sales_order_settlement_id, transaction_code, transaction_type, direction,
    amount_minor, currency_code, payment_method_code, status, source_context, source_type,
    source_id, related_transaction_id, initiated_by_user_id, confirmed_by_user_id,
    reason_code, reason, idempotency_key, occurred_at, confirmed_at
  ) values (
    v_tx_id, p_tenant_id, v_settlement_id,
    'PMT-' || upper(substr(replace(v_tx_id::text, '-', ''), 1, 16)),
    'refund', 'outflow', p_amount_minor, v_currency, trim(p_payment_method_code), 'confirmed',
    coalesce(nullif(trim(p_source_context), ''), 'manual_correction'),
    'sales_order', p_sales_order_id, p_related_transaction_id, p_actor_id, p_actor_id,
    trim(p_reason_code), nullif(trim(coalesce(p_reason, '')), ''),
    trim(p_idempotency_key), now(), now()
  );

  perform sales._recompute_sales_settlement(p_tenant_id, v_settlement_id);
  v_result := sales._settlement_mutation_snapshot(p_tenant_id, v_settlement_id, v_tx_id);

  insert into sales.outbox_messages(id, tenant_id, event_type, payload)
  values (
    gen_random_uuid(), p_tenant_id, 'sales.payment.refunded',
    jsonb_build_object(
      'salesOrderId', p_sales_order_id::text,
      'settlementId', v_settlement_id::text,
      'transactionId', v_tx_id::text,
      'amountMinor', p_amount_minor,
      'correlationId', v_correlation::text
    )
  );

  perform sales._complete_sales_idempotency(
    p_tenant_id,
    'record_sales_refund',
    trim(p_idempotency_key),
    'succeeded',
    'sales_payment_transaction',
    v_tx_id,
    v_result
  );

  return v_result;
end;
$$;

-- ---------------------------------------------------------------------------
-- void_sales_payment — append-only reversal; original row stays intact.
-- ---------------------------------------------------------------------------
create or replace function sales.void_sales_payment(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_store_id uuid,
  p_sales_order_id uuid,
  p_transaction_id uuid,
  p_reason_code text,
  p_idempotency_key text,
  p_payload_hash text,
  p_reason text default null,
  p_correlation_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = sales, iam, public, pg_temp
as $$
declare
  v_decision jsonb;
  v_settlement_id uuid;
  v_order_store uuid;
  v_src sales.sales_payment_transactions%rowtype;
  v_tx_id uuid := gen_random_uuid();
  v_result jsonb;
  v_correlation uuid := coalesce(p_correlation_id, gen_random_uuid());
begin
  perform sales._assert_sales_actor(p_tenant_id, p_actor_id, p_store_id, 'sales.payment.void');

  if nullif(trim(coalesce(p_reason_code, '')), '') is null
     or nullif(trim(coalesce(p_idempotency_key, '')), '') is null
     or nullif(trim(coalesce(p_payload_hash, '')), '') is null then
    raise exception using message = jsonb_build_object(
      'code', 'CONTEXT_INVALID',
      'message', 'Void context is invalid.'
    )::text;
  end if;

  select store_id into v_order_store
  from sales.sales_orders
  where tenant_id = p_tenant_id and id = p_sales_order_id;
  if not found or v_order_store is distinct from p_store_id then
    raise exception using message = jsonb_build_object(
      'code', 'REFERENCE_UNAVAILABLE',
      'message', 'Sales order was not found in store scope.'
    )::text;
  end if;

  v_decision := sales._begin_sales_idempotency(
    p_tenant_id,
    'void_sales_payment',
    trim(p_idempotency_key),
    trim(p_payload_hash),
    v_correlation
  );
  if v_decision->>'decision' = 'replay' then
    return v_decision->'result_snapshot';
  end if;
  if v_decision->>'decision' = 'in_progress' then
    raise exception using message = jsonb_build_object(
      'code', 'IDEMPOTENCY_CONFLICT',
      'message', 'Idempotency key is already in progress.'
    )::text;
  end if;

  v_settlement_id := sales._settlement_id_for_order(p_tenant_id, p_sales_order_id);

  select * into v_src
  from sales.sales_payment_transactions
  where tenant_id = p_tenant_id
    and id = p_transaction_id
    and sales_order_settlement_id = v_settlement_id
  for update;

  if not found then
    raise exception using message = jsonb_build_object(
      'code', 'REFERENCE_UNAVAILABLE',
      'message', 'Transaction was not found.'
    )::text;
  end if;
  if v_src.status <> 'confirmed' or v_src.transaction_type = 'reversal' then
    raise exception using message = jsonb_build_object(
      'code', 'STALE_DATA',
      'message', 'Only confirmed non-reversal transactions can be voided.'
    )::text;
  end if;

  if exists (
    select 1
    from sales.sales_payment_transactions existing
    where existing.tenant_id = p_tenant_id
      and existing.sales_order_settlement_id = v_settlement_id
      and existing.related_transaction_id = p_transaction_id
      and existing.transaction_type = 'reversal'
      and existing.status = 'confirmed'
  ) then
    raise exception using message = jsonb_build_object(
      'code', 'ALREADY_VOIDED',
      'message', 'Transaction already has a confirmed reversal.'
    )::text;
  end if;

  -- Append-only compensating reversal. Do not rewrite original monetary evidence.
  insert into sales.sales_payment_transactions(
    id, tenant_id, sales_order_settlement_id, transaction_code, transaction_type, direction,
    amount_minor, currency_code, payment_method_code, status, source_context, source_type,
    source_id, related_transaction_id, initiated_by_user_id, confirmed_by_user_id,
    reason_code, reason, idempotency_key, occurred_at, confirmed_at
  ) values (
    v_tx_id, p_tenant_id, v_settlement_id,
    'PMT-' || upper(substr(replace(v_tx_id::text, '-', ''), 1, 16)),
    'reversal',
    case when v_src.direction = 'inflow' then 'outflow' else 'inflow' end,
    v_src.amount_minor, v_src.currency_code, v_src.payment_method_code, 'confirmed',
    'manual_correction', 'sales_payment_transaction', p_transaction_id, p_transaction_id,
    p_actor_id, p_actor_id, trim(p_reason_code), nullif(trim(coalesce(p_reason, '')), ''),
    trim(p_idempotency_key), now(), now()
  );

  perform sales._recompute_sales_settlement(p_tenant_id, v_settlement_id);
  v_result := sales._settlement_mutation_snapshot(p_tenant_id, v_settlement_id, v_tx_id);

  insert into sales.outbox_messages(id, tenant_id, event_type, payload)
  values (
    gen_random_uuid(), p_tenant_id, 'sales.payment.voided',
    jsonb_build_object(
      'salesOrderId', p_sales_order_id::text,
      'settlementId', v_settlement_id::text,
      'voidedTransactionId', p_transaction_id::text,
      'reversalTransactionId', v_tx_id::text,
      'correlationId', v_correlation::text
    )
  );

  perform sales._complete_sales_idempotency(
    p_tenant_id,
    'void_sales_payment',
    trim(p_idempotency_key),
    'succeeded',
    'sales_payment_transaction',
    v_tx_id,
    v_result
  );

  return v_result;
end;
$$;

